using UnityEngine;
using UnityEditor;
using System.Collections.Generic;

/// <summary>
/// Slices the Character_ANIM_Sheets into 16x8 grids.
/// Sets _n variants to NormalMap texture type (unsliced).
/// </summary>

const string sheetBase = "Assets/Flynn/Sprites/Character_ANIM_Sheets";
const int cols = 16;
const int rows = 8;
const int cellWidth = 128; // 2048 / 16

// (assetPath, cellHeight)
var sheets = new List<(string path, int cellH)>
{
    ($"{sheetBase}/idle.png",   52), // 419/8 floor = 52
    ($"{sheetBase}/run.png",   53), // 430/8 floor = 53
    ($"{sheetBase}/swing.png", 59), // 475/8 floor = 59
};

// Direction names for sprite naming (row 0..7)
string[] dirNames = { "Down", "DownLeft", "Left", "UpLeft", "Up", "UpRight", "Right", "DownRight" };

int totalSprites = 0;

foreach (var (path, cellH) in sheets)
{
    var importer = AssetImporter.GetAtPath(path) as TextureImporter;
    if (importer == null)
    {
        Debug.LogError($"[SliceSheets] No importer for {path}");
        continue;
    }

    // Read existing settings
    var tex = AssetDatabase.LoadAssetAtPath<Texture2D>(path);
    Debug.Log($"[SliceSheets] {path} → {tex.width}x{tex.height}, cellSize={cellWidth}x{cellH}, rows={tex.height/cellH}");

    // Configure as Multiple sprite mode
    importer.textureType = TextureImporterType.Sprite;
    importer.spriteImportMode = SpriteImportMode.Multiple;
    importer.spritePixelsToUnits = 100;
    importer.filterMode = FilterMode.Bilinear;
    importer.textureCompression = TextureImporterCompression.Uncompressed;

    // Build sprite sheet metadata
    var spriteSheet = new SpriteSheetMetaData();
    var spritesList = new List<SpriteMetaData>();

    for (int row = 0; row < rows; row++)
    {
        for (int col = 0; col < cols; col++)
        {
            var meta = new SpriteMetaData
            {
                name = $"{System.IO.Path.GetFileNameWithoutExtension(path)}_{dirNames[row]}_{col}",
                rect = new Rect(col * cellWidth, (rows - 1 - row) * cellH, cellWidth, cellH),
                alignment = (int)SpriteAlignment.Center,
                pivot = new Vector2(0.5f, 0.5f)
            };
            spritesList.Add(meta);
        }
    }

    spriteSheet.sprites = spritesList.ToArray();
    importer.spriteSheet = spriteSheet;

    // Save and reimport
    EditorUtility.SetDirty(importer);
    importer.SaveAndReimport();

    // Count resulting sprites
    var loaded = AssetDatabase.LoadAllAssetRepresentationsAtPath(path);
    int spriteCount = 0;
    foreach (var obj in loaded)
    {
        if (obj is Sprite) spriteCount++;
    }
    totalSprites += spriteCount;
    Debug.Log($"[SliceSheets] {path} → {spriteCount} sprites sliced");
}

// ── Set _n variants to NormalMap type (unsliced, single texture) ──
string[] normalSheets = {
    $"{sheetBase}/idle_n.png",
    $"{sheetBase}/run_n.png",
    $"{sheetBase}/swing_n.png"
};

foreach (var nPath in normalSheets)
{
    var nImporter = AssetImporter.GetAtPath(nPath) as TextureImporter;
    if (nImporter == null)
    {
        Debug.LogError($"[SliceSheets] No importer for {nPath}");
        continue;
    }

    nImporter.textureType = TextureImporterType.NormalMap;
    nImporter.spriteImportMode = SpriteImportMode.None;
    nImporter.textureCompression = TextureImporterCompression.Uncompressed;
    nImporter.filterMode = FilterMode.Bilinear;

    EditorUtility.SetDirty(nImporter);
    nImporter.SaveAndReimport();

    Debug.Log($"[SliceSheets] {nPath} → set to NormalMap (unsliced)");
}

Debug.Log($"[SliceSheets] Done! Total sprites sliced: {totalSprites}");

