using UnityEngine;
using UnityEditor;
using System.Collections.Generic;
using System.Linq;

const string sheetBase = "Assets/Flynn/Sprites/Character_ANIM_Sheets";
const string animOut = "Assets/Flynn/Animations";
const float fps = 12f;
const int cols = 16;
const int rows = 8;

string[] dirNames = { "Down", "DownLeft", "Left", "UpLeft", "Up", "UpRight", "Right", "DownRight" };

// (animType, sheetPath, loop, outputFolder)
var animDefs = new List<(string type, string sheet, bool loop, string folder)>
{
    ("Idle",  $"{sheetBase}/idle.png",  true,  $"{animOut}/Idle8Dir"),
    ("Run",   $"{sheetBase}/run.png",   true,  $"{animOut}/Run8Dir"),
    ("Swing", $"{sheetBase}/swing.png", false, $"{animOut}/Swing8Dir"),
};

int clipsCreated = 0;
int clipsSkipped = 0;

foreach (var (type, sheetPath, loop, folder) in animDefs)
{
    if (!AssetDatabase.IsValidFolder(folder))
        AssetDatabase.CreateFolder(animOut, folder.Substring(animOut.Length + 1));

    // Load all sprites from the sheet
    var allObjects = AssetDatabase.LoadAllAssetRepresentationsAtPath(sheetPath);
    var allSprites = allObjects.OfType<Sprite>().ToList();

    if (allSprites.Count == 0)
    {
        Debug.LogError($"[Clips] No sprites found at {sheetPath}");
        continue;
    }

    // Group sprites by direction (row)
    for (int dirIdx = 0; dirIdx < dirNames.Length; dirIdx++)
    {
        string dirName = dirNames[dirIdx];
        string clipName = $"Flynn_{type}_{dirName}";
        string outPath = $"{folder}/{clipName}.anim";

        // Collect sprites for this direction (row), ordered by column
        var dirSprites = new List<Sprite>();
        for (int col = 0; col < cols; col++)
        {
            string spriteName = $"{System.IO.Path.GetFileNameWithoutExtension(sheetPath)}_{dirName}_{col}";
            var sprite = allSprites.FirstOrDefault(s => s.name == spriteName);
            if (sprite != null)
                dirSprites.Add(sprite);
            else
                Debug.LogWarning($"[Clips] Missing sprite: {spriteName}");
        }

        if (dirSprites.Count == 0)
        {
            Debug.LogWarning($"[Clips] No sprites for {clipName}");
            continue;
        }

        // Delete existing clip to recreate with new frame count
        if (AssetDatabase.LoadAssetAtPath<AnimationClip>(outPath) != null)
            AssetDatabase.DeleteAsset(outPath);

        // Create the animation clip
        var clip = new AnimationClip { frameRate = fps };

        var binding = new EditorCurveBinding
        {
            type = typeof(SpriteRenderer),
            path = "",
            propertyName = "m_Sprite"
        };

        var keys = new ObjectReferenceKeyframe[dirSprites.Count];
        for (int i = 0; i < dirSprites.Count; i++)
            keys[i] = new ObjectReferenceKeyframe { time = i / fps, value = dirSprites[i] };

        AnimationUtility.SetObjectReferenceCurve(clip, binding, keys);

        var settings = AnimationUtility.GetAnimationClipSettings(clip);
        settings.loopTime = loop;
        AnimationUtility.SetAnimationClipSettings(clip, settings);
        clip.wrapMode = loop ? WrapMode.Loop : WrapMode.Once;

        // Add Attack tag for Swing clips
        if (type == "Swing")
        {
            var events = new AnimationEvent[1];
            events[0] = new AnimationEvent { time = 0f, functionName = "OnAttackStart" };
            AnimationUtility.SetAnimationEvents(clip, events);
        }

        AssetDatabase.CreateAsset(clip, outPath);
        EditorUtility.SetDirty(clip);
        clipsCreated++;
    }
}

AssetDatabase.SaveAssets();
AssetDatabase.Refresh();

Debug.Log($"[Clips] Done! Created {clipsCreated} clips, skipped {clipsSkipped}");

