// Check the naming pattern of the re-sliced sprites
var path = "Assets/Flynn/Sprites/Character_ANIM_Sheets/idle.png";
var allObj = UnityEditor.AssetDatabase.LoadAllAssetRepresentationsAtPath(path);
int count = 0;
foreach (var obj in allObj)
{
    if (obj is UnityEngine.Sprite s)
    {
        count++;
        if (count <= 20)
            UnityEngine.Debug.Log($"  {s.name}");
    }
}
UnityEngine.Debug.Log($"[Check] Total: {count} sprites");

// Also check run and swing naming
foreach (var sheet in new[] { "run.png", "swing.png" })
{
    var sp = $"Assets/Flynn/Sprites/Character_ANIM_Sheets/{sheet}";
    var objs = UnityEditor.AssetDatabase.LoadAllAssetRepresentationsAtPath(sp);
    int c = 0;
    string firstName = "";
    foreach (var obj in objs)
    {
        if (obj is UnityEngine.Sprite s)
        {
            c++;
            if (string.IsNullOrEmpty(firstName)) firstName = s.name;
        }
    }
    UnityEngine.Debug.Log($"[Check] {sheet}: {c} sprites, first='{firstName}'");
}

using UnityEngine;
using UnityEditor;
using System.Collections.Generic;

const string sheetBase = "Assets/Flynn/Sprites/Character_ANIM_Sheets";
const string animOut = "Assets/Flynn/Animations";
const float fps = 12f;
const int cols = 16;
const int rows = 8;

string[] dirNames = { "Down", "DownLeft", "Left", "UpLeft", "Up", "UpRight", "Right", "DownRight" };

// Sheet definitions: (type, filename, loop, output subfolder)
var sheetDefs = new[]
{
    ("Idle",  "idle.png",  true,  "Idle8Dir"),
    ("Run",   "run.png",   true,  "Run8Dir"),
    ("Swing", "swing.png", false, "Swing8Dir"),
};

int clipsCreated = 0;

foreach (var def in sheetDefs)
{
    string type = def.Item1;
    string file = def.Item2;
    bool loop = def.Item3;
    string folder = def.Item4;

    string sheetPath = $"{sheetBase}/{file}";
    string sheetName = System.IO.Path.GetFileNameWithoutExtension(file); // "idle", "run", "swing"

    var allObj = AssetDatabase.LoadAllAssetRepresentationsAtPath(sheetPath);
    var allSprites = new List<Sprite>();
    foreach (var obj in allObj)
    {
        if (obj is Sprite sp) allSprites.Add(sp);
    }

    if (allSprites.Count != cols * rows)
    {
        Debug.LogError($"[Rebuild] {file} has {allSprites.Count} sprites, expected {cols * rows}");
        continue;
    }

    string folderPath = $"{animOut}/{folder}";
    if (!AssetDatabase.IsValidFolder(folderPath))
        AssetDatabase.CreateFolder(animOut, folder);

    // Rebuild clip for each direction
    for (int dirIdx = 0; dirIdx < dirNames.Length; dirIdx++)
    {
        string dirName = dirNames[dirIdx];
        string clipName = $"Flynn_{type}_{dirName}";
        string outPath = $"{folderPath}/{clipName}.anim";

        // Collect 16 sprites for this direction (row)
        // Sequential naming: row 0 = sprites 0-15, row 1 = 16-31, etc.
        int rowStart = dirIdx * cols;
        var dirSprites = new List<Sprite>();
        for (int col = 0; col < cols; col++)
        {
            var sprite = allSprites[rowStart + col];
            if (sprite != null)
                dirSprites.Add(sprite);
        }

        if (dirSprites.Count == 0)
        {
            Debug.LogWarning($"[Rebuild] No sprites for {clipName}");
            continue;
        }

        // Delete existing clip
        if (AssetDatabase.LoadAssetAtPath<AnimationClip>(outPath) != null)
            AssetDatabase.DeleteAsset(outPath);

        var clip = new AnimationClip { frameRate = fps };

        var binding = new EditorCurveBinding
        {
            type = typeof(SpriteRenderer),
            path = "",
            propertyName = "m_Sprite"
        };

        var keys = new ObjectReferenceKeyframe[dirSprites.Count];
        for (int i = 0; i < dirSprites.Count; i++)
            keys[i] = new ObjectReferenceKeyframe { time = i / fps, value = dirSprites[i] };

        AnimationUtility.SetObjectReferenceCurve(clip, binding, keys);

        var settings = AnimationUtility.GetAnimationClipSettings(clip);
        settings.loopTime = loop;
        AnimationUtility.SetAnimationClipSettings(clip, settings);
        clip.wrapMode = loop ? WrapMode.Loop : WrapMode.Once;

        AssetDatabase.CreateAsset(clip, outPath);
        EditorUtility.SetDirty(clip);
        clipsCreated++;
    }
}

AssetDatabase.SaveAssets();
AssetDatabase.Refresh();
Debug.Log($"[Rebuild] Created {clipsCreated} clips with new sprite references");

