// Check current material/shader setup on the Visual SpriteRenderer
var player = UnityEngine.GameObject.Find("Player");
var visual = player.transform.Find("Visual");
var sr = visual.GetComponent<UnityEngine.SpriteRenderer>();

var mat = sr.sharedMaterial;
if (mat != null)
{
    var shader = mat.shader;
    UnityEngine.Debug.Log($"[Check] Material: {mat.name}");
    UnityEngine.Debug.Log($"[Check] Shader: {shader.name}");

    // List all shader properties
    for (int i = 0; i < shader.GetPropertyCount(); i++)
    {
        var name = shader.GetPropertyName(i);
        var type = shader.GetPropertyType(i);
        if (type == UnityEngine.Rendering.ShaderPropertyType.Texture)
        {
            var tex = mat.GetTexture(name);
            UnityEngine.Debug.Log($"[Check]   Texture prop '{name}' = {(tex != null ? tex.name : "NULL")}");
        }
    }
}

// Check FlynnAnimationDriver normal map references
var driver = player.GetComponent("FlynnAnimationDriver") as MonoBehaviour;
if (driver != null)
{
    var so = new UnityEditor.SerializedObject(driver);
    var props = new[] { "_spriteMaterial", "_idleNormal", "_runNormal", "_swingNormal" };
    foreach (var pName in props)
    {
        var prop = so.FindProperty(pName);
        if (prop != null)
            UnityEngine.Debug.Log($"[Check] {pName} = {(prop.objectReferenceValue != null ? prop.objectReferenceValue.name : "NULL")}");
        else
            UnityEngine.Debug.Log($"[Check] {pName} = PROP NOT FOUND");
    }
}

