// Switch the material to URP Sprite-Lit-Default and assign the normal map
var player = UnityEngine.GameObject.Find("Player");
var visual = player.transform.Find("Visual");
var sr = visual.GetComponent<UnityEngine.SpriteRenderer>();

var mat = sr.sharedMaterial;
if (mat != null)
{
    // Switch shader
    var newShader = UnityEngine.Shader.Find("Universal Render Pipeline/2D/Sprite-Lit-Default");
    if (newShader != null)
    {
        UnityEditor.Undo.RecordObject(mat, "Switch to URP Sprite-Lit-Default");
        mat.shader = newShader;

        // Assign idle normal map to the new _NormalMap property
        var idleNormal = UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.Texture>(
            "Assets/Flynn/Sprites/Character_ANIM_Sheets/idle_n.png");
        if (idleNormal != null)
            mat.SetTexture("_NormalMap", idleNormal);

        UnityEngine.Debug.Log($"[Fix] Shader → {mat.shader.name}");
        UnityEngine.Debug.Log($"[Fix] _NormalMap → {mat.GetTexture("_NormalMap")?.name ?? "NULL"}");
        UnityEditor.EditorUtility.SetDirty(mat);
    }
    else
    {
        UnityEngine.Debug.LogError("[Fix] URP Sprite-Lit-Default shader not found!");
    }
}

