using UnityEngine;
using UnityEditor;
using System.Collections.Generic;

const float newFps = 24f;
const string animBase = "Assets/Flynn/Animations";
string[] folders = { "Idle8Dir", "Run8Dir", "Swing8Dir" };
var binding = new EditorCurveBinding { type = typeof(SpriteRenderer), path = "", propertyName = "m_Sprite" };

int updated = 0;

foreach (var folder in folders)
{
    var guids = AssetDatabase.FindAssets("t:AnimationClip", new[] { $"{animBase}/{folder}" });
    foreach (var guid in guids)
    {
        var path = AssetDatabase.GUIDToAssetPath(guid);
        var clip = AssetDatabase.LoadAssetAtPath<AnimationClip>(path);
        if (clip == null) continue;

        var curve = AnimationUtility.GetObjectReferenceCurve(clip, binding);
        if (curve == null || curve.Length == 0) continue;

        // Recalculate keyframe times at new FPS
        for (int i = 0; i < curve.Length; i++)
            curve[i].time = i / newFps;

        clip.frameRate = newFps;
        AnimationUtility.SetObjectReferenceCurve(clip, binding, curve);

        var settings = AnimationUtility.GetAnimationClipSettings(clip);
        // loopTime stays the same
        AnimationUtility.SetAnimationClipSettings(clip, settings);

        EditorUtility.SetDirty(clip);
        updated++;
    }
}

AssetDatabase.SaveAssets();
Debug.Log($"[FPS] Updated {updated} clips to {newFps} fps");

