// Check what shader the sprite test material actually resolves to at runtime
var mat = UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.Material>("Assets/Flynn/Materials/sprite test.mat");
if (mat != null)
{
    UnityEngine.Debug.Log($"Material: {mat.name}");
    UnityEngine.Debug.Log($"Shader: {mat.shader.name}");
    UnityEngine.Debug.Log($"RenderQueue: {mat.renderQueue}");

    // List all properties
    var shader = mat.shader;
    for (int i = 0; i < shader.GetPropertyCount(); i++)
    {
        var name = shader.GetPropertyName(i);
        var type = shader.GetPropertyType(i);
        if (type == UnityEngine.Rendering.ShaderPropertyType.Texture)
        {
            var tex = mat.GetTexture(name);
            UnityEngine.Debug.Log($"  {name} ({type}) = {(tex != null ? tex.name : "NULL")}");
        }
        else if (type == UnityEngine.Rendering.ShaderPropertyType.Float || type == UnityEngine.Rendering.ShaderPropertyType.Range)
        {
            UnityEngine.Debug.Log($"  {name} ({type}) = {mat.GetFloat(name)}");
        }
        else if (type == UnityEngine.Rendering.ShaderPropertyType.Color)
        {
            UnityEngine.Debug.Log($"  {name} ({type}) = {mat.GetColor(name)}");
        }
        else if (type == UnityEngine.Rendering.ShaderPropertyType.Vector)
        {
            UnityEngine.Debug.Log($"  {name} ({type}) = {mat.GetVector(name)}");
        }
    }

    // Check keywords
    foreach (var kw in mat.shaderKeywords)
        UnityEngine.Debug.Log($"  Keyword: {kw}");
}

