Shader "Flynn/CharacterSpriteLit"
{
    // URP 2D-lit sprite with outline + color pop for the player character.
    // Uses the 2D renderer light pipeline (Sprite-Lit-Default pass) for normal maps
    // and 2D lights, then adds a pixel outline and color grading on top.
    Properties
    {
        [PerRendererData] _MainTex ("Sprite Texture", 2D) = "white" {}
        _Color ("Tint", Color) = (1,1,1,1)

        [Header(Outline)]
        _OutlineColor ("Outline Color", Color) = (0,0,0,1)
        _OutlineWidth ("Outline Width", Range(0, 4)) = 1.0
        _OutlineSoftness ("Outline Softness", Range(0, 2)) = 0.5

        [Header(Color Pop)]
        _Saturation ("Saturation", Range(0, 3)) = 1.4
        _Brightness ("Brightness", Range(-0.5, 0.5)) = 0.05
        _Contrast ("Contrast", Range(0, 3)) = 1.2
        _PosterizeSteps ("Posterize Steps", Range(2, 32)) = 12

        [Header(Normal Map)]
        [PerRendererData] _NormalMap ("Normal Map", 2D) = "bump" {}

        // Stencil (required for 2D renderer)
        _StencilComp ("Stencil Comp", Float) = 8
        _Stencil ("Stencil ID", Float) = 0
        _StencilOp ("Stencil Op", Float) = 0
        _StencilWriteMask ("Stencil Write Mask", Float) = 255
        _StencilReadMask ("Stencil Read Mask", Float) = 255
        _ColorMask ("Color Mask", Float) = 15

        [Toggle(UNITY_UI_ALPHACLIP)] _UseUIAlphaClip ("Use Alpha Clip", Float) = 0
    }

    SubShader
    {
        Tags
        {
            "RenderPipeline" = "UniversalPipeline"
            "Queue" = "Transparent"
            "IgnoreProjector" = "True"
            "RenderType" = "Transparent"
            "PreviewType" = "Plane"
            "CanUseSpriteAtlas" = "True"
        }

        Stencil
        {
            Ref [_Stencil]
            Comp [_StencilComp]
            Pass [_StencilOp]
            ReadMask [_StencilReadMask]
            WriteMask [_StencilWriteMask]
        }

        Cull Off
        ZWrite Off
        Blend One OneMinusSrcAlpha
        ColorMask [_ColorMask]

        Pass
        {
            Name "Default"
            Tags { "LightMode" = "Universal2D" }

        HLSLPROGRAM
            #pragma vertex vert
            #pragma fragment frag
            #pragma target 2.0
            #pragma multi_compile_instancing
            #pragma multi_compile _ UNITY_UI_CLIP_RECT UNITY_UI_ALPHACLIP
            #pragma multi_compile _ _NORMALMAP

            #include "Packages/com.unity.render-pipelines.universal/ShaderLibrary/Core.hlsl"
            #include "Packages/com.unity.render-pipelines.universal/Shaders/2D/Include/Sprite2D.hlsl"

            struct appdata
            {
                float4 vertex : POSITION;
                float4 color : COLOR;
                float2 uv : TEXCOORD0;
                UNITY_VERTEX_INPUT_INSTANCE_ID
            };

            struct v2f
            {
                float4 vertex : SV_POSITION;
                half4 color : COLOR;
                float2 uv : TEXCOORD0;
                float4 worldPosition : TEXCOORD1;
                UNITY_VERTEX_INPUT_INSTANCE_ID
            };

            TEXTURE2D(_MainTex);
            SAMPLER(sampler_MainTex);
            half4 _Color;
            float4 _MainTex_TexelSize;

            #ifdef _NORMALMAP
            TEXTURE2D(_NormalMap);
            SAMPLER(sampler_NormalMap);
            #endif

            // Outline
            half4 _OutlineColor;
            float _OutlineWidth;
            float _OutlineSoftness;

            // Color pop
            float _Saturation;
            float _Brightness;
            float _Contrast;
            float _PosterizeSteps;

            v2f vert(appdata v)
            {
                v2f o;
                UNITY_SETUP_INSTANCE_ID(v);
                UNITY_TRANSFER_INSTANCE_ID(v, o);
                o.worldPosition = v.vertex;
                o.vertex = TransformObjectToHClip(v.vertex.xyz);
                o.uv = v.uv;
                o.color = v.color * _Color;
                return o;
            }

            // Sample alpha at an offset (in texels)
            float SampleAlpha(float2 uv, float2 offset)
            {
                float2 sampleUv = uv + offset * _MainTex_TexelSize.xy;
                return SAMPLE_TEXTURE2D(_MainTex, sampler_MainTex, sampleUv).a;
            }

            half4 frag(v2f i) : SV_Target
            {
                // ── Sample sprite ──
                half4 c = SAMPLE_TEXTURE2D(_MainTex, sampler_MainTex, i.uv) * i.color;

                // ── Outline detection ──
                // Check alpha of neighbors up to OutlineWidth texels away
                float maxNeighborAlpha = 0;
                float w = _OutlineWidth;
                float step = 1.0;

                // 8-directional sampling at OutlineWidth distance
                float2 dirs[8] = {
                    float2(1, 0), float2(-1, 0), float2(0, 1), float2(0, -1),
                    float2(0.707, 0.707), float2(-0.707, 0.707), float2(0.707, -0.707), float2(-0.707, -0.707)
                };

                // Multi-step: sample at increasing distances
                for (float d = 1.0; d <= w; d += 1.0)
                {
                    for (int j = 0; j < 8; j++)
                    {
                        float a = SampleAlpha(i.uv, dirs[j] * d);
                        maxNeighborAlpha = max(maxNeighborAlpha, a);
                    }
                }

                // If this pixel is transparent but neighbors are opaque → draw outline
                float outlineMask = maxNeighborAlpha * (1.0 - c.a);

                // Soft edge for anti-aliasing
                if (_OutlineSoftness > 0.001)
                    outlineMask = smoothstep(0.0, _OutlineSoftness * 0.1, outlineMask);

                // Draw outline under the sprite too (outline peeking out)
                float outlineUnderSprite = 0;
                if (c.a > 0.1)
                {
                    // Sample just outside the sprite edge for inner outline
                    float edgeAlpha = 0;
                    for (int k = 0; k < 8; k++)
                    {
                        float a = SampleAlpha(i.uv, dirs[k] * 1.0);
                        edgeAlpha = max(edgeAlpha, 1.0 - a);
                    }
                    outlineUnderSprite = edgeAlpha * step;
                }

                // Blend outline color
                half3 outlineRgb = _OutlineColor.rgb * _OutlineColor.a;
                c.rgb = lerp(c.rgb, outlineRgb, saturate(outlineMask + outlineUnderSprite * 0.3));
                c.a = max(c.a, outlineMask * _OutlineColor.a);

                // ── Color pop ──
                // Brightness
                c.rgb += _Brightness;

                // Contrast
                c.rgb = (c.rgb - 0.5) * _Contrast + 0.5;

                // Saturation (Rec.709 luminance)
                float lum = dot(c.rgb, float3(0.2126, 0.7152, 0.0722));
                c.rgb = lerp(lum.xxx, c.rgb, _Saturation);

                // Posterize: snap each channel to discrete steps
                float steps = max(2.0, _PosterizeSteps);
                c.rgb = floor(c.rgb * steps + 0.5) / steps;

                // Premultiplied alpha
                c.rgb *= c.a;

                #ifdef UNITY_UI_CLIP_RECT
                c.a *= UnityGet2DClipping(i.worldPosition.xy, _ClipRect);
                #endif

                #ifdef UNITY_UI_ALPHACLIP
                clip(c.a - 0.001);
                #endif

                return c;
            }
        ENDHLSL
        }

        // Shadow caster pass for 2D shadows
        Pass
        {
            Name "ShadowCaster"
            Tags { "LightMode" = "ShadowCaster2D" }

            Cull Off
            ZWrite Off

        HLSLPROGRAM
            #pragma vertex vert
            #pragma fragment frag
            #pragma target 2.0

            #include "Packages/com.unity.render-pipelines.universal/ShaderLibrary/Core.hlsl"
            #include "Packages/com.unity.render-pipelines.universal/Shaders/2D/Include/Sprite2D.hlsl"

            TEXTURE2D(_MainTex);
            SAMPLER(sampler_MainTex);
            half4 _Color;

            struct appdata
            {
                float4 vertex : POSITION;
                float4 color : COLOR;
                float2 uv : TEXCOORD0;
            };

            struct v2f
            {
                float4 vertex : SV_POSITION;
                float2 uv : TEXCOORD0;
                half4 color : COLOR;
            };

            v2f vert(appdata v)
            {
                v2f o;
                o.vertex = TransformObjectToHClip(v.vertex.xyz);
                o.uv = v.uv;
                o.color = v.color * _Color;
                return o;
            }

            half4 frag(v2f i) : SV_Target
            {
                half4 c = SAMPLE_TEXTURE2D(_MainTex, sampler_MainTex, i.uv) * i.color;
                clip(c.a - 0.01);
                return half4(1, 1, 1, c.a);
            }
        ENDHLSL
        }
    }
}

