var shader = UnityEngine.Shader.Find("Flynn/CharacterSpriteLit");
var mat = new UnityEngine.Material(shader);
mat.name = "M_CharacterSprite";

// Outline
mat.SetColor("_OutlineColor", new UnityEngine.Color(0.04f, 0.02f, 0.0f, 1f));
mat.SetFloat("_OutlineWidth", 1.5f);
mat.SetFloat("_OutlineSoftness", 0.5f);

// Color pop
mat.SetFloat("_Saturation", 1.4f);
mat.SetFloat("_Brightness", 0.05f);
mat.SetFloat("_Contrast", 1.2f);
mat.SetFloat("_PosterizeSteps", 12f);

// Normal map
var idleNormal = UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.Texture>(
    "Assets/Flynn/Sprites/Character_ANIM_Sheets/idle_n.png");
if (idleNormal != null)
    mat.SetTexture("_NormalMap", idleNormal);

string matPath = "Assets/Flynn/Materials/M_CharacterSprite.mat";
if (UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.Material>(matPath) != null)
    UnityEditor.AssetDatabase.DeleteAsset(matPath);

UnityEditor.AssetDatabase.CreateAsset(mat, matPath);
UnityEditor.EditorUtility.SetDirty(mat);
UnityEditor.AssetDatabase.SaveAssets();

// Assign to the Visual SpriteRenderer
var player = UnityEngine.GameObject.Find("Player");
var visual = player.transform.Find("Visual");
var sr = visual.GetComponent<UnityEngine.SpriteRenderer>();
UnityEditor.Undo.RecordObject(sr, "Assign CharacterSprite material");
sr.sharedMaterial = mat;

// Also update the FlynnAnimationDriver's _spriteMaterial reference
var driver = player.GetComponent("FlynnAnimationDriver") as MonoBehaviour;
if (driver != null)
{
    var so = new UnityEditor.SerializedObject(driver);
    var matProp = so.FindProperty("_spriteMaterial");
    if (matProp != null)
    {
        matProp.objectReferenceValue = mat;
        so.ApplyModifiedProperties();
    }
}

UnityEngine.Debug.Log($"[Setup] Material created and assigned. NormalMap={idleNormal?.name ?? "NULL"}");

