args.script:
// Wait for shader import, then reassign
UnityEditor.AssetDatabase.Refresh(UnityEditor.ImportAssetOptions.ForceUpdate);

var shader = UnityEngine.Shader.Find("Flynn/CharacterSpriteLit");
if (shader == null)
{
    UnityEngine.Debug.LogError("Shader still not found after refresh!");
}
else
{
    UnityEngine.Debug.Log($"Shader found: {shader.name}, passCount={shader.passCount}");

    // Update the existing material
    var mat = UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.Material>("Assets/Flynn/Materials/M_CharacterSprite.mat");
    if (mat != null)
    {
        mat.shader = shader;
        UnityEditor.EditorUtility.SetDirty(mat);
        UnityEditor.AssetDatabase.SaveAssets();
        UnityEngine.Debug.Log($"Updated material shader to {shader.name}");
    }
}

