using UnityEngine;
using UnityEditor;
using System.Collections.Generic;

const string sheetBase = "Assets/Flynn/Sprites/Character_ANIM_Sheets";
const string animOut = "Assets/Flynn/Animations";
const float fps = 24f;
const int cols = 16;
const int rows = 8;
const int halfFrames = 8; // 16 / 2

string[] dirNames = { "Down", "DownLeft", "Left", "UpLeft", "Up", "UpRight", "Right", "DownRight" };

// Load swing sprites
string sheetPath = $"{sheetBase}/swing.png";
var allObj = AssetDatabase.LoadAllAssetRepresentationsAtPath(sheetPath);
var allSprites = new List<Sprite>();
foreach (var obj in allObj) { if (obj is Sprite sp) allSprites.Add(sp); }
Debug.Log($"[SwingSplit] Loaded {allSprites.Count} swing sprites");

var binding = new EditorCurveBinding { type = typeof(SpriteRenderer), path = "", propertyName = "m_Sprite" };

int clipsCreated = 0;

foreach (var (folder, suffix, startFrame, frameCount, loop) in new[] {
    ("SwingWindup8Dir",  "Windup",  0, halfFrames, true),   // frames 0-7, loops (holds on last)
    ("SwingRelease8Dir", "Release", halfFrames, halfFrames, false), // frames 8-15, non-looping
})
{
    string folderPath = $"{animOut}/{folder}";
    if (!AssetDatabase.IsValidFolder(folderPath))
        AssetDatabase.CreateFolder(animOut, folder);

    for (int dirIdx = 0; dirIdx < dirNames.Length; dirIdx++)
    {
        string dir = dirNames[dirIdx];
        string clipName = $"Flynn_Swing{suffix}_{dir}";
        string outPath = $"{folderPath}/{clipName}.anim";

        // Delete existing
        if (AssetDatabase.LoadAssetAtPath<AnimationClip>(outPath) != null)
            AssetDatabase.DeleteAsset(outPath);

        // Collect frames for this direction
        int rowStart = dirIdx * cols;
        var sprites = new List<Sprite>();
        for (int i = 0; i < frameCount; i++)
        {
            var sprite = allSprites[rowStart + startFrame + i];
            if (sprite != null) sprites.Add(sprite);
        }

        if (sprites.Count == 0) { Debug.LogWarning($"[SwingSplit] No sprites for {clipName}"); continue; }

        var clip = new AnimationClip { frameRate = fps };

        var keys = new ObjectReferenceKeyframe[sprites.Count];
        for (int i = 0; i < sprites.Count; i++)
            keys[i] = new ObjectReferenceKeyframe { time = i / fps, value = sprites[i] };

        AnimationUtility.SetObjectReferenceCurve(clip, binding, keys);

        var settings = AnimationUtility.GetAnimationClipSettings(clip);
        settings.loopTime = loop;
        AnimationUtility.SetAnimationClipSettings(clip, settings);
        clip.wrapMode = loop ? WrapMode.Loop : WrapMode.Once;

