using UnityEngine;
using UnityEditor;
using UnityEditor.Animations;
using System.Collections.Generic;

const string animBase = "Assets/Flynn/Animations";
const string ctrlPath = animBase + "/Flynn_AnimatorController.controller";

string[] dirNames = { "Down", "DownLeft", "Left", "UpLeft", "Up", "UpRight", "Right", "DownRight" };

// Delete existing controller
if (AssetDatabase.LoadAssetAtPath<AnimatorController>(ctrlPath) != null)
    AssetDatabase.DeleteAsset(ctrlPath);

// Load all clips
var clips = new Dictionary<string, AnimationClip>();
var clipDefs = new[] {
    ("Idle",  "Idle8Dir"),
    ("Run",   "Run8Dir"),
    ("Swing", "Swing8Dir"),
    ("SwingWindup",  "SwingWindup8Dir"),
    ("SwingRelease", "SwingRelease8Dir"),
};

foreach (var def in clipDefs)
{
    string type = def.Item1;
    string folder = def.Item2;
    foreach (var dir in dirNames)
    {
        string clipName = $"Flynn_{type}_{dir}";
        string path = $"{animBase}/{folder}/{clipName}.anim";
        var clip = AssetDatabase.LoadAssetAtPath<AnimationClip>(path);
        if (clip != null)
            clips[clipName] = clip;
        else
            Debug.LogWarning($"[Controller] Missing clip: {clipName}");
    }
}
Debug.Log($"[Controller] Loaded {clips.Count} clips");

// Create controller
var ctrl = AnimatorController.CreateAnimatorControllerAtPath(ctrlPath);
ctrl.AddParameter("Speed",         AnimatorControllerParameterType.Float);
ctrl.AddParameter("IsGrounded",    AnimatorControllerParameterType.Bool);
ctrl.AddParameter("FacingDir",     AnimatorControllerParameterType.Int);
ctrl.AddParameter("Jump",          AnimatorControllerParameterType.Trigger);
ctrl.AddParameter("Swing",         AnimatorControllerParameterType.Trigger);
ctrl.AddParameter("SwingWindup",  AnimatorControllerParameterType.Trigger);
ctrl.AddParameter("Hold",          AnimatorControllerParameterType.Bool);
ctrl.AddParameter("Throw",         AnimatorControllerParameterType.Trigger);
ctrl.AddParameter("Scan",          AnimatorControllerParameterType.Trigger);

var sm = ctrl.layers[0].stateMachine;
var states = new Dictionary<string, AnimatorState>();

// Locomotion: Idle & Run per direction
float xBase = 0f;
foreach (var dir in dirNames)
{
    var idle = AddState(sm, clips, $"Idle_{dir}", $"Flynn_Idle_{dir}", new Vector3(xBase, 0, 0));
    var run  = AddState(sm, clips, $"Run_{dir}",  $"Flynn_Run_{dir}",  new Vector3(xBase + 300, 0, 0));
    states[$"Idle_{dir}"] = idle;
    states[$"Run_{dir}"]  = run;
    xBase += 400f;
}
sm.defaultState = states["Idle_Down"];

// Full Swing states (instant swing, no charge)
float xSwing = 0f;
float ySwing = -300f;
foreach (var dir in dirNames)
{
    var swing = AddState(sm, clips, $"Swing_{dir}", $"Flynn_Swing_{dir}", new Vector3(xSwing, ySwing, 0));
    swing.tag = "Attack";
    states[$"Swing_{dir}"] = swing;
    xSwing += 300f;
}

// SwingWindup states (charge phase, looping first 8 frames)
float xWindup = 0f;
float yWindup = -600f;
foreach (var dir in dirNames)
{
    var windup = AddState(sm, clips, $"SwingWindup_{dir}", $"Flynn_SwingWindup_{dir}", new Vector3(xWindup, yWindup, 0));
    windup.tag = "Attack";
    states[$"SwingWindup_{dir}"] = windup;
    xWindup += 300f;
}

// SwingRelease states (release from charge, last 8 frames)
float xRelease = 0f;
float yRelease = -900f;
foreach (var dir in dirNames)
{
    var release = AddState(sm, clips, $"SwingRelease_{dir}", $"Flynn_SwingRelease_{dir}", new Vector3(xRelease, yRelease, 0));
    release.tag = "Attack";
    states[$"SwingRelease_{dir}"] = release;
    xRelease += 300f;
}

// ── Locomotion transitions ──
foreach (var dir in dirNames)
{
    int dirVal = System.Array.IndexOf(dirNames, dir);
    var idle = states[$"Idle_{dir}"];
    var run  = states[$"Run_{dir}"];

    var t = MkTrans(idle, run);
    t.AddCondition(AnimatorConditionMode.Greater, 0.1f, "Speed");
    t.AddCondition(AnimatorConditionMode.Equals, dirVal, "FacingDir");

    t = MkTrans(run, idle);
    t.AddCondition(AnimatorConditionMode.Less, 0.1f, "Speed");

    t = MkTrans(run, idle);
    t.AddCondition(AnimatorConditionMode.NotEqual, dirVal, "FacingDir");
}

// Cross-direction idle transitions
for (int i = 0; i < dirNames.Length; i++)
{
    for (int j = 0; j < dirNames.Length; j++)
    {
        if (i == j) continue;
        var t = MkTrans(states[$"Idle_{dirNames[i]}"], states[$"Idle_{dirNames[j]}"]);
        t.AddCondition(AnimatorConditionMode.Equals, j, "FacingDir");
    }
}

// ── Full Swing (instant): AnyState → Swing → Idle ──
foreach (var dir in dirNames)
{
    int dirVal = System.Array.IndexOf(dirNames, dir);
    var swingState = states[$"Swing_{dir}"];

    var anyTrans = sm.AddAnyStateTransition(swingState);
    anyTrans.hasExitTime = false;
    anyTrans.duration = 0f;
    anyTrans.canTransitionToSelf = false;
    anyTrans.AddCondition(AnimatorConditionMode.If, 0f, "Swing");
    // Only go to full swing if NOT in a windup state (windup → release instead)
    anyTrans.AddCondition(AnimatorConditionMode.IfNot, 0f, "SwingWindup");

    var exitTrans = swingState.AddTransition(states[$"Idle_{dir}"]);
    exitTrans.hasExitTime = true;
    exitTrans.exitTime = 0.85f;
    exitTrans.duration = 0.15f;
}

// ── SwingWindup: AnyState → SwingWindup (looping charge) ──
foreach (var dir in dirNames)
{
    int dirVal = System.Array.IndexOf(dirNames, dir);
    var windupState = states[$"SwingWindup_{dir}"];

    var anyTrans = sm.AddAnyStateTransition(windupState);
    anyTrans.hasExitTime = false;
    anyTrans.duration = 0f;
    anyTrans.canTransitionToSelf = false;
    anyTrans.AddCondition(AnimatorConditionMode.If, 0f, "SwingWindup");
    anyTrans.AddCondition(AnimatorConditionMode.Equals, dirVal, "FacingDir");
}

// ── SwingWindup → SwingRelease (on Swing trigger from charge) ──
foreach (var dir in dirNames)
{
    var windupState = states[$"SwingWindup_{dir}"];
    var releaseState = states[$"SwingRelease_{dir}"];

    var trans = windupState.AddTransition(releaseState);
    trans.hasExitTime = false;
    trans.duration = 0f;
    trans.AddCondition(AnimatorConditionMode.If, 0f, "Swing");
}

// ── SwingRelease → Idle (exit after release) ──
foreach (var dir in dirNames)
{
    var releaseState = states[$"SwingRelease_{dir}"];

    var exitTrans = releaseState.AddTransition(states[$"Idle_{dir}"]);
    exitTrans.hasExitTime = true;
    exitTrans.exitTime = 0.85f;
    exitTrans.duration = 0.15f;
}

// ── Cancel windup → back to idle (if SwingWindup cancelled) ──
foreach (var dir in dirNames)
{
    var windupState = states[$"SwingWindup_{dir}"];
    // If windup is interrupted (e.g. move away), transition back to idle
    // We'll handle this via the Swing trigger being consumed
    // For now, the windup loops until Swing trigger fires
}

// Re-assign the controller on the Player Visual
var player = UnityEngine.GameObject.Find("Player");
if (player != null)
{
    var visual = player.transform.Find("Visual");
    if (visual != null)
    {
        var animator = visual.GetComponent<UnityEngine.Animator>();
        if (animator != null)
            animator.runtimeAnimatorController = ctrl;
    }
}

EditorUtility.SetDirty(ctrl);
AssetDatabase.SaveAssets();
Debug.Log($"[Controller] Built 8-dir controller with {states.Count} states (including windup+release)");

AnimatorState AddState(AnimatorStateMachine sm, Dictionary<string, AnimationClip> clips, string stateName, string clipName, Vector3 pos)
{
    var state = sm.AddState(stateName, pos);
    if (clips.TryGetValue(clipName, out var clip))
        state.motion = clip;
    else
        Debug.LogWarning($"[Controller] Clip '{clipName}' not found for state '{stateName}'");
    return state;
}

AnimatorStateTransition MkTrans(AnimatorState from, AnimatorState to)
{
    var t = from.AddTransition(to);
    t.hasExitTime = false;
    t.duration = 0f;
    t.exitTime = 0f;
    return t;
}

